def semver_sort(versions):
    def parse_version(v):
        # Split by '+' to remove build metadata
        v = v.split('+')[0]

        # Split by '-' to separate core version and pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            core = v
            prerelease_parts = None

        # Parse core version (MAJOR.MINOR.PATCH)
        major, minor, patch = map(int, core.split('.'))

        return (major, minor, patch, prerelease_parts)

    def prerelease_key(prerelease_parts):
        # If no pre-release, it sorts after any pre-release version
        if prerelease_parts is None:
            return (1,)  # Higher than any pre-release

        # Convert pre-release parts to comparable tuples
        result = [0]  # Lower than no pre-release
        for part in prerelease_parts:
            if part.isdigit():
                # All-digit identifiers: (0, numeric_value)
                result.append((0, int(part)))
            else:
                # Non-digit identifiers: (1, string_value)
                result.append((1, part))

        return tuple(result)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_parts = parse_version(version)
        return (major, minor, patch, prerelease_key(prerelease_parts), index)

    indexed_versions = list(enumerate(versions))
    indexed_versions.sort(key=sort_key)

    return [v for _, v in indexed_versions]

